const body = $json.body || $json;

let source = 'form';
let name = '';
let phone = '';
let email = '';
let transcript = '';
let isVapiToolCall = false;
let toolCalls = [];
let vapiCallId = null;

if (body.message && body.message.type) {
  const msg = body.message;
  if (msg.type === 'tool-calls' || msg.type === 'function-call') {
    isVapiToolCall = true;
    source = 'vapi_tool';
    toolCalls = msg.toolCallList || msg.toolCalls || [];
    if (!Array.isArray(toolCalls) && msg.functionCall) {
      toolCalls = [{ id: msg.functionCall.id || 'unknown', name: msg.functionCall.name, arguments: msg.functionCall.parameters || msg.functionCall.arguments || {} }];
    }
    vapiCallId = (msg.call && msg.call.id) || null;
    name = (msg.customer && msg.customer.name) || '';
    phone = (msg.customer && msg.customer.number) || '';
  } else {
    source = 'vapi';
    transcript = msg.transcript || (msg.artifact && msg.artifact.transcript) || '';
    name = (msg.customer && msg.customer.name) || (body.customer && body.customer.name) || '';
    phone = (msg.customer && msg.customer.number) || (body.customer && body.customer.number) || '';
    email = (msg.analysis && msg.analysis.structuredData && msg.analysis.structuredData.email) || '';
  }
} else if (Object.prototype.hasOwnProperty.call(body, 'chatId') || Object.prototype.hasOwnProperty.call(body, 'widgetId')) {
  source = 'website_chat';
  transcript = body.message || body.text || '';
  name = body.name || '';
  phone = body.phone || '';
  email = body.email || '';
} else {
  source = 'form';
  transcript = body.message || body.notes || body.details || '';
  name = body.name || body.fullName || '';
  phone = body.phone || body.phoneNumber || '';
  email = body.email || '';
}

return [{
  json: {
    source,
    isVapiToolCall,
    toolCalls,
    vapiCallId,
    rawName: (name || '').toString().trim(),
    rawPhone: (phone || '').toString().trim(),
    rawEmail: (email || '').toString().trim().toLowerCase(),
    rawTranscript: (transcript || '').toString().trim(),
    receivedAt: new Date().toISOString()
  }
}];

const d = $json;
const toolCalls = d.toolCalls || [];
const results = [];

function makeResult(toolCallId, data) {
  return {
    toolCallId: toolCallId || 'unknown',
    result: typeof data === 'string' ? data : JSON.stringify(data)
  };
}

for (const tc of toolCalls) {
  const id = tc.id || (tc.toolCall && tc.toolCall.id) || 'unknown';
  const name = (tc.name || (tc.function && tc.function.name) || '').toLowerCase();
  let args = tc.arguments || (tc.function && tc.function.arguments) || {};
  if (typeof args === 'string') {
    try { args = JSON.parse(args); } catch(e) { args = {}; }
  }

  try {
    if (name === 'qualify_lead') {
      results.push(makeResult(id, {
        status: 'ok',
        message: 'Lead data received. Full qualification will run on end-of-call. Provide name, phone, intent, location, budget, timeline if available.',
        received: { name: args.name || d.rawName, phone: args.phone || d.rawPhone, intent: args.intent || null }
      }));
    } else if (name === 'find_properties' || name === 'check_property') {
      results.push(makeResult(id, {
        status: 'ok',
        action: name,
        filters: {
          location: args.location || null,
          budget_min: args.budget_min || args.budgetMin || null,
          budget_max: args.budget_max || args.budgetMax || args.budget || null,
          property_type: args.property_type || args.propertyType || null,
          bedrooms: args.bedrooms || null,
          status: 'Active'
        },
        message: 'Property search will use Active listings matching location, budget range, type and bedrooms. Top matches with scores returned after full processing.'
      }));
    } else if (name === 'check_availability') {
      const date = args.date || args.datetime || args.preferred_date || null;
      const time = args.time || args.preferred_time || null;
      if (!date && !time) {
        results.push(makeResult(id, { status: 'need_input', message: 'Please provide a preferred date or date+time for availability check.' }));
      } else {
        results.push(makeResult(id, {
          status: 'ok',
          message: 'Availability will be checked against the agent calendar. Specific slot will be verified before any booking.',
          requested: { date, time }
        }));
      }
    } else if (name === 'book_viewing') {
      const dt = args.datetime || args.date || args.preferred_datetime || null;
      if (!dt) {
        results.push(makeResult(id, { status: 'need_input', message: 'A specific date/time is required to book a viewing. Please confirm preferred slot.' }));
      } else {
        results.push(makeResult(id, {
          status: 'ok',
          message: 'Booking request received. Slot will be verified against live calendar and confirmed only if available.',
          requested_datetime: dt
        }));
      }
    } else if (name === 'create_lead' || name === 'update_lead') {
      results.push(makeResult(id, {
        status: 'ok',
        action: name,
        message: 'Lead create/update will be performed with phone as primary key and email as secondary. Existing records are updated, never duplicated.',
        payload: {
          name: args.name || d.rawName,
          phone: args.phone || d.rawPhone,
          email: args.email || d.rawEmail,
          intent: args.intent || null
        }
      }));
    } else {
      results.push(makeResult(id, { status: 'unknown_action', message: `Action '${name}' is not supported. Supported: qualify_lead, find_properties, check_property, check_availability, book_viewing, create_lead, update_lead.` }));
    }
  } catch (err) {
    results.push(makeResult(id, { status: 'error', message: 'Tool execution failed safely. Please try again or provide more details.' }));
  }
}

if (results.length === 0) {
  results.push({ toolCallId: 'unknown', result: JSON.stringify({ status: 'error', message: 'No valid tool calls found.' }) });
}

return [{ json: { vapiResponse: { results }, source: d.source, isVapiToolCall: true } }];

const d = $json;

const systemPrompt = `You are a real estate lead qualification assistant. Read the conversation/notes and extract ONLY the following fields as strict JSON, with no extra text, no markdown fences. Use null for anything not mentioned - never invent data.

Schema:
{
  "name": string|null,
  "phone": string|null,
  "email": string|null,
  "intent": "buyer"|"seller"|"renter"|"unknown",
  "location": string|null,
  "budget": string|null,
  "budget_min": number|null,
  "budget_max": number|null,
  "property_type": string|null,
  "bedrooms": number|null,
  "timeline": string|null,
  "property_id": string|null,
  "appointment_requested": boolean,
  "appointment_datetime": string|null,
  "appointment_date_only": string|null,
  "notes": string|null,
  "ai_summary": string|null
}`;

const userPrompt = `Lead source: ${d.source}
Name provided on form: ${d.rawName}
Phone provided on form: ${d.rawPhone}
Email provided on form: ${d.rawEmail}

Conversation / message content:
${d.rawTranscript}

Extract the fields now as strict JSON only. Never invent missing information.`;

return [{ json: { ...d, aiSystemPrompt: systemPrompt, aiUserPrompt: userPrompt, aiRetryCount: 0 } }];

const base = $('Build AI Prompt').item.json;
let aiText = '';
let parseError = null;

try {
  aiText = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
} catch (e) {
  aiText = '';
  parseError = 'No content from AI';
}
if (!aiText) aiText = '{}';

let parsed = {};
let isValid = false;
try {
  const cleaned = aiText.toString().replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
  if (typeof parsed === 'object' && parsed !== null) {
    isValid = true;
  }
} catch (e) {
  parseError = e.message;
  parsed = {};
}

if (!isValid && (base.aiRetryCount || 0) < 1) {
  return [{
    json: {
      ...base,
      aiRetryCount: 1,
      needsAiRetry: true,
      aiParseError: parseError || 'Invalid JSON'
    }
  }];
}

const intent = (parsed.intent || 'unknown').toString().toLowerCase();
const safeIntent = ['buyer','seller','renter'].includes(intent) ? intent : 'unknown';

const result = {
  isDuplicate: base.isDuplicate,
  existingRowNumber: base.existingRowNumber,
  source: base.source,
  receivedAt: new Date().toISOString(),
  name: parsed.name || base.rawName || 'Unknown',
  phone: parsed.phone || base.rawPhone || '',
  email: (parsed.email || base.rawEmail || '').toLowerCase(),
  intent: safeIntent,
  location: parsed.location || null,
  budget: parsed.budget || null,
  budget_min: parsed.budget_min || null,
  budget_max: parsed.budget_max || null,
  property_type: parsed.property_type || null,
  bedrooms: parsed.bedrooms != null ? Number(parsed.bedrooms) : null,
  timeline: parsed.timeline || null,
  property_id: parsed.property_id || null,
  appointment_requested: parsed.appointment_requested === true,
  appointment_datetime: parsed.appointment_datetime || null,
  appointment_date_only: parsed.appointment_date_only || null,
  notes: parsed.notes || null,
  ai_summary: parsed.ai_summary || (base.rawTranscript ? base.rawTranscript.substring(0, 300) : null),
  aiParseError: parseError || null,
  aiValid: isValid
};

return [{ json: result }];

const base = $('Build AI Prompt').item.json;
let aiText = '';
let parseError = null;
try {
  aiText = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content;
} catch (e) { aiText = ''; parseError = 'Retry failed'; }
if (!aiText) aiText = '{}';

let parsed = {};
try {
  const cleaned = aiText.toString().replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
  parsed = {};
}

const intent = (parsed.intent || 'unknown').toString().toLowerCase();
const safeIntent = ['buyer','seller','renter'].includes(intent) ? intent : 'unknown';

return [{
  json: {
    isDuplicate: base.isDuplicate,
    existingRowNumber: base.existingRowNumber,
    source: base.source,
    receivedAt: new Date().toISOString(),
    name: parsed.name || base.rawName || 'Unknown',
    phone: parsed.phone || base.rawPhone || '',
    email: (parsed.email || base.rawEmail || '').toLowerCase(),
    intent: safeIntent,
    location: parsed.location || null,
    budget: parsed.budget || null,
    budget_min: parsed.budget_min || null,
    budget_max: parsed.budget_max || null,
    property_type: parsed.property_type || null,
    bedrooms: parsed.bedrooms != null ? Number(parsed.bedrooms) : null,
    timeline: parsed.timeline || null,
    property_id: parsed.property_id || null,
    appointment_requested: parsed.appointment_requested === true,
    appointment_datetime: parsed.appointment_datetime || null,
    appointment_date_only: parsed.appointment_date_only || null,
    notes: parsed.notes || null,
    ai_summary: parsed.ai_summary || (base.rawTranscript ? base.rawTranscript.substring(0, 300) : null),
    aiParseError: parseError || null,
    aiValid: !parseError,
    aiRetried: true
  }
}];

const d = $json;
let score = 0;

if (d.phone) score += 15;
if (d.email) score += 10;

const timeline = (d.timeline || '').toString().toLowerCase();
if (/asap|immediate|this week|0-30|30 day/.test(timeline)) score += 25;
else if (/1-3 month|next month/.test(timeline)) score += 15;
else if (/3-6 month/.test(timeline)) score += 8;
else if (timeline) score += 3;

if (d.budget || d.budget_max) score += 15;
if (d.property_type) score += 8;
if (d.bedrooms) score += 5;
if (d.location) score += 7;
if (d.appointment_requested === true) score += 15;

score = Math.max(0, Math.min(100, score));

let leadCategory = 'COLD';
if (score >= 80) leadCategory = 'HOT';
else if (score >= 50) leadCategory = 'WARM';

return [{ json: { ...d, leadScore: score, leadCategory } }];

const allProps = $input.all().map(i => i.json).filter(p => p && (p.Status || p.status || '').toString().toLowerCase() === 'active');
const lead = $('Lead Scoring').item.json;

function parseNum(v) {
  if (v == null || v === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
  return isNaN(n) ? null : n;
}

const loc = (lead.location || '').toString().toLowerCase().trim();
const pType = (lead.property_type || '').toString().toLowerCase().trim();
const bedsWanted = lead.bedrooms != null ? Number(lead.bedrooms) : null;
let budgetMin = parseNum(lead.budget_min);
let budgetMax = parseNum(lead.budget_max) || parseNum(lead.budget);

const scored = [];

for (const p of allProps) {
  let score = 0;
  const pLoc = (p.Location || p.location || '').toString().toLowerCase();
  const pTypeVal = (p.Property_Type || p.property_type || p.Type || '').toString().toLowerCase();
  const pBeds = parseNum(p.Bedrooms || p.bedrooms);
  const pPrice = parseNum(p.Price || p.price);

  if (loc && pLoc) {
    if (pLoc.includes(loc) || loc.includes(pLoc)) score += 40;
    else if (pLoc.split(/[\s,]+/).some(w => loc.includes(w) || w.includes(loc))) score += 20;
  }

  if (pType && pTypeVal) {
    if (pTypeVal === pType || pTypeVal.includes(pType) || pType.includes(pTypeVal)) score += 25;
  }

  if (bedsWanted != null && pBeds != null) {
    if (pBeds === bedsWanted) score += 20;
    else if (Math.abs(pBeds - bedsWanted) === 1) score += 10;
  }

  if (pPrice != null) {
    if (budgetMax != null && pPrice <= budgetMax * 1.1) score += 15;
    if (budgetMin != null && pPrice >= budgetMin * 0.9) score += 10;
    if (budgetMax == null && budgetMin == null) score += 5;
  }

  if (score > 0) {
    scored.push({
      ...p,
      matchScore: Math.min(100, score),
      propertyId: p.Property_ID || p.property_id || p.id || null
    });
  }
}

scored.sort((a, b) => b.matchScore - a.matchScore);
const top = scored.slice(0, 5);

return [{
  json: {
    ...lead,
    matchedProperties: top,
    matchCount: top.length,
    propertyMatchError: top.length === 0 ? 'No active properties matched the criteria' : null
  }
}];

const events = $input.all().map(i => i.json);
const lead = $('Filter Properties by Budget').item.json || $('Skip Property Matching').item.json;

const hasSpecificDt = lead.appointment_datetime && !isNaN(new Date(lead.appointment_datetime).getTime());
const hasDateOnly = lead.appointment_date_only && !hasSpecificDt;

let slotAvailable = false;
let requestedStartTime = null;
let requestedEndTime = null;
let availableSlots = [];
let appointmentStatus = 'not_requested';
let calendarNote = '';

if (hasSpecificDt) {
  const requestedStart = new Date(lead.appointment_datetime);
  const requestedEnd = new Date(requestedStart.getTime() + 30 * 60000);
  requestedStartTime = requestedStart.toISOString();
  requestedEndTime = requestedEnd.toISOString();

  const conflict = events.some(e => {
    const evStartRaw = (e.start && (e.start.dateTime || e.start.date)) || e.start;
    const evEndRaw = (e.end && (e.end.dateTime || e.end.date)) || e.end;
    if (!evStartRaw || !evEndRaw) return false;
    const evStart = new Date(evStartRaw);
    const evEnd = new Date(evEndRaw);
    return requestedStart < evEnd && requestedEnd > evStart;
  });

  slotAvailable = !conflict;
  appointmentStatus = slotAvailable ? 'slot_available_ready_to_book' : 'requested_slot_unavailable';
  calendarNote = slotAvailable ? 'Requested slot is free' : 'Requested slot conflicts with existing event';
} else if (hasDateOnly) {
  const dayStart = new Date(lead.appointment_date_only + 'T09:00:00');
  const dayEnd = new Date(lead.appointment_date_only + 'T17:00:00');
  const busy = events.filter(e => {
    const s = new Date((e.start && (e.start.dateTime || e.start.date)) || e.start);
    const en = new Date((e.end && (e.end.dateTime || e.end.date)) || e.end);
    return s < dayEnd && en > dayStart;
  });
  const windows = [
    { start: '09:00', end: '12:00' },
    { start: '13:00', end: '17:00' }
  ];
  for (const w of windows) {
    const ws = new Date(lead.appointment_date_only + 'T' + w.start + ':00');
    const we = new Date(lead.appointment_date_only + 'T' + w.end + ':00');
    const blocked = busy.some(e => {
      const s = new Date((e.start && (e.start.dateTime || e.start.date)) || e.start);
      const en = new Date((e.end && (e.end.dateTime || e.end.date)) || e.end);
      return ws < en && we > s;
    });
    if (!blocked) availableSlots.push({ date: lead.appointment_date_only, window: w.start + '-' + w.end });
  }
  appointmentStatus = availableSlots.length > 0 ? 'date_available_options' : 'date_fully_booked';
  calendarNote = availableSlots.length > 0 ? 'Available windows on requested date' : 'No free windows on requested date';
} else {
  appointmentStatus = 'need_preferred_datetime';
  calendarNote = 'Customer did not provide a preferred date or time. Ask for preferred viewing slot.';
}

return [{
  json: {
    ...lead,
    slotAvailable,
    requestedStartTime,
    requestedEndTime,
    availableSlots,
    appointmentStatus,
    calendarNote
  }
}];

parameters.message:
=A high-priority lead just came in and needs immediate follow-up.

Name: {{ $json.name }}
Phone: {{ $json.phone }}
Intent: {{ $json.intent }}
Location: {{ $json.location }}
Budget: {{ $json.budget || ($json.budget_min && $json.budget_max ? $json.budget_min + '-' + $json.budget_max : 'n/a') }}
Property: {{ $json.property_id || ($json.matchedProperties && $json.matchedProperties[0] && ($json.matchedProperties[0].propertyId || $json.matchedProperties[0].Location)) || 'n/a' }}
Timeline: {{ $json.timeline }}
Lead Score: {{ $json.leadScore }} ({{ $json.leadCategory }})
AI Summary: {{ $json.ai_summary || 'n/a' }}
Appointment status: {{ $json.appointmentStatus }}

Source: {{ $json.source }}

=The Real Estate Lead Conversion workflow failed.

Node: {{ $json.execution.lastNodeExecuted }}
Error: {{ $json.execution.error?.message }}
Execution URL: {{ $json.execution.url }}

Please check the failed lead manually so it is not lost.

Common causes: AI failure, Google Sheets failure, Calendar failure, invalid input, property not found, duplicate handling.
